  ReceiptInstallerWindow(string path){
   runtime=path;Text="Install Game Receipts";BackColor=Color.FromArgb(29,8,39);ForeColor=Color.White;Font=new Font("Segoe UI",10);ClientSize=new Size(940,660);MinimumSize=new Size(780,580);AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.None;DoubleBuffered=true;
