   var body=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22,8,22,18),ColumnCount=1,RowCount=7};body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<7;i++)body.RowStyles.Add(new RowStyle(i==3?SizeType.Percent:SizeType.AutoSize,i==3?100:0));Controls.Add(body);body.BringToFront();
