   var browse=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,Margin=new Padding(0,8,0,4)};var folder=Button("Choose Folder",Color.FromArgb(0,154,174));var zip=Button("Choose Archive",Color.FromArgb(170,0,255));browse.Controls.Add(folder);browse.Controls.Add(zip);scan.Text="Scan Receipts";Style(scan,Color.FromArgb(215,83,0));browse.Controls.Add(scan);actions.AddRange(new Control[]{folder,zip,scan});body.Controls.Add(browse,0,1);
   source.Dock=DockStyle.Fill;source.ReadOnly=true;source.BackColor=Color.FromArgb(43,29,53);source.ForeColor=Color.White;source.BorderStyle=BorderStyle.FixedSingle;source.Margin=new Padding(0,4,0,10);body.Controls.Add(source,0,2);
   preview.Dock=DockStyle.Fill;preview.ReadOnly=true;preview.AllowUserToAddRows=false;preview.AllowUserToDeleteRows=false;preview.AllowUserToResizeRows=false;preview.RowHeadersVisible=false;preview.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;preview.BackgroundColor=Color.FromArgb(43,29,53);preview.BorderStyle=BorderStyle.None;preview.EnableHeadersVisualStyles=false;preview.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(0,123,136);preview.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;preview.DefaultCellStyle.BackColor=Color.FromArgb(43,29,53);preview.DefaultCellStyle.ForeColor=Color.White;preview.DefaultCellStyle.SelectionBackColor=Color.FromArgb(110,40,160);preview.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;preview.DefaultCellStyle.WrapMode=DataGridViewTriState.True;
   preview.Columns.Add("game","Game");preview.Columns.Add("installed","Installed?");preview.Columns.Add("issued","Receipt issued");preview.Columns.Add("destination","Destination / result");preview.Columns[0].FillWeight=80;preview.Columns[1].FillWeight=35;preview.Columns[2].FillWeight=65;preview.Columns[3].FillWeight=190;body.Controls.Add(preview,0,3);
   include.Text="Include games that aren't currently installed. This will create receipt folders under your Windows profile.";include.AutoSize=true;include.Margin=new Padding(0,12,0,6);include.CheckedChanged+=delegate{if(previewing)RenderPreview();UpdateEnabled();};actions.Add(include);body.Controls.Add(include,0,4);
   var bottom=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,Margin=new Padding(0,5,0,5)};install.Text="Install Receipts";Style(install,Color.FromArgb(66,135,12));cancel.Text="Cancel";Style(cancel,Color.FromArgb(43,29,53));bottom.Controls.Add(install);bottom.Controls.Add(cancel);body.Controls.Add(bottom,0,5);
