   scan.Click+=async delegate{await Run(async()=>{
    plan="";previewing=false;rows=new object[0];issues=new object[0];preview.Rows.Clear();status.Text="Scanning subfolders and checking signatures. Cancel stops the scan; nothing is installed.";
    var data=await Call(new{action="scan",source=source.Text});rows=Wire.Get(data,"entries") as object[]??new object[0];issues=Wire.Get(data,"issues") as object[]??new object[0];previewing=true;RenderPreview();
    if(Wire.Get(data,"cancelled") is bool&&(bool)data["cancelled"]){status.Text="Scan cancelled. Nothing was installed.";return;}
    plan=Wire.Text(data,"planPath");
   });};
