  }
  void RenderPreview(){
   preview.Rows.Clear();int shown=0;
   foreach(var raw in rows){var row=Wire.Map(raw);bool installed=Convert.ToBoolean(row["installed"]);if(!include.Checked&&!installed)continue;shown++;preview.Rows.Add(Wire.Text(row,"game"),installed?"Yes":"No",DateTimeOffset.Parse(Wire.Text(row,"mintedUtc")).ToLocalTime().ToString("g"),FormatDestination(Wire.Text(row,"destination")));}
   foreach(var raw in issues){var row=Wire.Map(raw);preview.Rows.Add("Skipped","","",Wire.Text(row,"source")+": "+Wire.Text(row,"message"));}
   status.Text="Showing "+shown+" of "+rows.Length+" games. "+issues.Length+" skipped items.";
  }
  void ChooseFolder(){try{string downloads=Path.Combine(ShareClient.DataRoot,"Games");string initial=Directory.Exists(source.Text)?source.Text:Directory.Exists(downloads)?downloads:ShareClient.DataRoot;string selected=ReceiptFolderPicker.Pick(Handle,initial);if(selected!=null){source.Text=selected;plan="";previewing=false;rows=new object[0];issues=new object[0];preview.Rows.Clear();UpdateEnabled();}}catch(Exception e){status.Text=e.Message;}}
