  protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==0x84&&WindowState!=FormWindowState.Maximized&&m.Result==new IntPtr(1)){var p=PointToClient(new Point((short)((long)m.LParam&0xffff),(short)(((long)m.LParam>>16)&0xffff)));bool l=p.X<6,r=p.X>=Width-6,t=p.Y<6,b=p.Y>=Height-6;m.Result=new IntPtr(t?(l?13:r?14:12):b?(l?16:r?17:15):l?10:r?11:1);}}
  static string FormatDestination(string path){return path.Replace(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"%LOCALAPPDATA%").Replace("\\Packages\\","\\Packages\\\r\n").Replace("\\LocalState\\","\r\n\\LocalState\\");}
  static Label Label(string text){return new Label{Text=text,AutoSize=true,Margin=new Padding(0,4,0,5)};}
  static void Style(Button b,Color color){b.AutoSize=true;b.FlatStyle=FlatStyle.Flat;b.BackColor=color;b.ForeColor=Color.White;b.Padding=new Padding(10,6,10,6);b.Margin=new Padding(0,0,9,5);b.FlatAppearance.BorderColor=Color.FromArgb(175,160,180);}
