  void UpdateEnabled(){foreach(var c in actions)c.Enabled=!busy;scan.Enabled=!busy&&source.Text.Length>0;install.Enabled=!busy&&plan.Length>0&&rows.Any(r=>include.Checked||Convert.ToBoolean(Wire.Map(r)["installed"]));cancel.Enabled=true;}
  async Task Run(Func<Task> action){if(busy)return;busy=true;UpdateEnabled();try{await action();}catch(Exception e){status.Text=e.Message;}finally{busy=false;job="";UpdateEnabled();}}
  async Task<Dictionary<string,object>> Call(object request){string root=Path.Combine(ShareClient.DataRoot,"ReceiptInstaller");ShareClient.PrivateFolder(root);job=Path.Combine(root,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));ShareClient.PrivateFolder(job);string requestPath=Path.Combine(job,"request-private.json");File.WriteAllText(requestPath,Wire.Json.Serialize(request));string current=job;return await Task.Run(()=>{var start=new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32\\WindowsPowerShell\\v1.0\\powershell.exe"),Arguments="-NoProfile -MTA -ExecutionPolicy Bypass -File \""+Path.Combine(runtime,"InstallerWorker.ps1")+"\" -RequestPath \""+requestPath+"\"",UseShellExecute=false,CreateNoWindow=true};using(var process=Process.Start(start))process.WaitForExit();string result=Path.Combine(current,"result-private.json");if(!File.Exists(result))throw new IOException("The installer worker could not finish. No receipt results are available.");var row=Wire.Map(Wire.Json.DeserializeObject(File.ReadAllText(result)));if(!(Wire.Get(row,"success") is bool&&(bool)row["success"]))throw new IOException(Wire.Text(row,"message"));return Wire.Map(row["data"]);});}
